namespace WPFUI.Factories;
using WPFUI.Models;
using System.IO;
using System.Xml;
using WPFUI.Models;
using WPFUI.Shared;
internal static class QuestFactory
{   
    private static readonly string GAME_DATA_FILENAME = Path.Combine(AppContext.BaseDirectory, "GameData", "Quests.xml");
    private static readonly List<Quest> _quests = new List<Quest>();

    static QuestFactory()
    {
        if (File.Exists(GAME_DATA_FILENAME))
        {
            XmlDocument data = new XmlDocument();
            data.LoadXml(File.ReadAllText(GAME_DATA_FILENAME));
            LoadQuestsFromNodes(data.SelectNodes("/Quests/Quest"));
        }
    }

    private static void LoadQuestsFromNodes(XmlNodeList nodes)
    {
        foreach(XmlNode node in nodes)
        {
            List<ItemQuantity> itemsToComplete = new List<ItemQuantity>();
            List<ItemQuantity> rewardItems = new List<ItemQuantity>();
            foreach(XmlNode childNode in node.SelectNodes("./rewardItems/Item"))
            {
                rewardItems.Add(new ItemQuantity(childNode.AttributeAsInt("ID"), childNode.AttributeAsInt("Quantity")));
            }
            _quests.Add(new Quest(node.AttributeAsInt("ID"),
                                node.SelectSingleNode("./Name")?.InnerText ?? "",
                                node.SelectSingleNode("./Description")?.InnerText ?? "",
                                node.AttributeAsInt("RewardedExperiencePoints"),
                                node.AttributeAsInt("RewardedGold"),
                                rewardItems,
                                itemsToComplete
            ));
        }
    }

    internal static Quest GetQuestById(int id)
    {
        Quest? quest = _quests.FirstOrDefault(q => q.Id == id);
        if (quest == null)
        {
            throw new ArgumentException($"QuestId '{id}' does not exist", nameof(id));
        }
        return quest;
    }
}

